#!/usr/bin/env python3
"""Independent oracle/golden comparison; all generated bytes stay in /tmp."""
import json
import os
from pathlib import Path
import shlex
import subprocess
import tempfile

ROOT = Path(__file__).resolve().parents[1]


def build(output, source=None):
    command = shlex.split(os.environ.get("CC", "cc"))
    command += shlex.split(os.environ.get("CFLAGS", "-g -O2"))
    command += ["-std=c11", "-Wall", "-Wextra", "-Werror", "-I" + str(ROOT / "src"),
                "-I" + str(ROOT / "src/core"), "-I" + str(ROOT / "tests"),
                str(ROOT / "tests/test_core_evidence_codec.c"), str(ROOT / "tests/evidence_json.c"),
                str(source or ROOT / "src/core/evidence_codec.c"),
                str(ROOT / "src/core/evidence_replay.c"), str(ROOT / "src/core/wait_metrics.c"),
                str(ROOT / "src/core/contract_json.c"), "-o", str(output)]
    subprocess.run(command, check=True, cwd=ROOT, capture_output=True, text=True)


def main():
    with tempfile.TemporaryDirectory(prefix="pgwt-codec-oracle-") as tmp:
        tmp = Path(tmp)
        binary = tmp / "codec-test"
        build(binary)
        oracle = ROOT / "contracts/evidence-v1/codec/oracle"
        result = subprocess.run(["python3", "-B", str(oracle / "enc.py")], cwd=tmp,
                                check=True, capture_output=True, text=True)
        values = json.loads((tmp / "values.json").read_text())
        assert values == json.loads((oracle / "values.json").read_text())
        for name in ("ex1.bin", "ex2.bin", "ex3.bin"):
            assert (tmp / name).read_bytes() == (ROOT / "contracts/evidence-v1/codec/fixtures" / name).read_bytes()
        subprocess.run([str(binary), "--case", "golden_646_bytes", "--write-golden", str(tmp / "encoded.bin")],
                       cwd=ROOT, check=True)
        assert (tmp / "encoded.bin").read_bytes() == (tmp / "all.bin").read_bytes()
        print("codec oracle enc.py + values.json + ex1-3.bin: 646/646 bytes identical PASS")


if __name__ == "__main__":
    main()
